<?php
declare(strict_types=1);require __DIR__.'/app.php';
if(current_user())redirect(current_user()['role']==='cliente'?'my-account':'dashboard');$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
  try{verify_csrf();$name=trim((string)($_POST['name']??''));$email=strtolower(trim((string)($_POST['email']??'')));$phone=trim((string)($_POST['phone']??''));$document=trim((string)($_POST['document_number']??''));$password=(string)($_POST['password']??'');$confirm=(string)($_POST['confirm_password']??'');
    if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||$document==='')throw new RuntimeException('Completa tu nombre, correo y documento de identidad.');if(strlen($password)<10)throw new RuntimeException('La contraseña debe tener al menos 10 caracteres.');if($password!==$confirm)throw new RuntimeException('Las contraseñas no coinciden.');
    db()->beginTransaction();$s=db()->prepare('SELECT id,user_id,email,document_number FROM clients WHERE email=? OR document_number=? LIMIT 1');$s->execute([$email,$document]);$existing=$s->fetch();if($existing){if($existing['user_id']||strtolower($existing['email'])!==$email||$existing['document_number']!==$document)throw new RuntimeException('No pudimos validar ese perfil. Confirma el correo y documento con recepción.');$s=db()->prepare("INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,'cliente')");$s->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT)]);$uid=(int)db()->lastInsertId();db()->prepare('UPDATE clients SET user_id=?,name=?,phone=? WHERE id=?')->execute([$uid,$name,$phone?:null,$existing['id']]);}else{$s=db()->prepare("INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,'cliente')");$s->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT)]);$uid=(int)db()->lastInsertId();$s=db()->prepare('INSERT INTO clients(user_id,name,email,phone,document_number) VALUES(?,?,?,?,?)');$s->execute([$uid,$name,$email,$phone?:null,$document]);}db()->commit();
    session_regenerate_id(true);$_SESSION['user']=['id'=>$uid,'name'=>$name,'email'=>$email,'role'=>'cliente','profile_image'=>null];redirect('my-account');
  }catch(Throwable $e){try{if(db()->inTransaction())db()->rollBack();}catch(Throwable $ignored){}$error=$e instanceof PDOException?'Ese correo o documento ya está registrado.':$e->getMessage();}
}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Crear cuenta · Mutatio</title><link rel="stylesheet" href="assets/app.css"><link rel="stylesheet" href="assets/extra.css"></head><body class="login-page"><main class="auth-wrap"><a class="login-brand" href="index.php"><span class="brand-mark">M</span><span>MUTATIO <small>TRAINING CLUB</small></span></a><section class="auth-card"><span class="eyebrow">PORTAL DE CLIENTES</span><h1>Crear cuenta</h1><p>Registra tu acceso para consultar tu membresía y tus pagos.</p><?php if($error): ?><div class="alert error"><?=h($error)?></div><?php endif; ?><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><label>Nombre completo<input name="name" required autocomplete="name" value="<?=h($_POST['name']??'')?>"></label><label>Correo electrónico<input type="email" name="email" required autocomplete="email" value="<?=h($_POST['email']??'')?>"></label><label>Teléfono (opcional)<input name="phone" autocomplete="tel" value="<?=h($_POST['phone']??'')?>"></label><label>Documento / CI<input name="document_number" required value="<?=h($_POST['document_number']??'')?>"></label><label>Contraseña<input type="password" name="password" minlength="10" required autocomplete="new-password"></label><label>Confirmar contraseña<input type="password" name="confirm_password" minlength="10" required autocomplete="new-password"></label><button class="btn primary wide">Crear cuenta <span>↗</span></button></form><p class="auth-foot"><a href="index.php?view=login">← Volver al inicio de sesión</a></p><div class="auth-note">Este formulario crea cuentas de cliente. Si ya estás registrado, confirma tu correo y documento. El personal requiere invitación del administrador.</div></section></main></body></html>
